<style>
.performance-hero{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:24px;align-items:stretch;padding:28px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,#fff,#f7fafc);margin-bottom:18px}.performance-hero h2{font-size:clamp(1.8rem,3vw,3rem);margin:.35rem 0}.performance-hero p{max-width:820px;color:var(--muted)}.performance-score{border:1px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;justify-content:center;background:#fff}.performance-score span,.performance-score small,.performance-metrics span,.performance-metrics small,.feedback-grid span,.feedback-grid small{color:var(--muted)}.performance-score strong{font-size:3.2rem;line-height:1;margin:.45rem 0}.performance-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:18px}.performance-metrics article,.feedback-grid article{border:1px solid var(--line);border-radius:18px;padding:18px;background:#fff}.performance-metrics strong,.feedback-grid strong{display:block;font-size:1.55rem;margin:.35rem 0}.performance-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px;align-items:start}.performance-layout main{display:grid;gap:18px}.performance-layout aside{display:grid;gap:18px;position:sticky;top:18px}.performance-side-card{border:1px solid var(--line);border-radius:20px;padding:20px;background:#fff}.status-callout{padding:14px;border-radius:14px;background:#f6f8fb;margin:14px 0}.status-callout span{display:block;color:var(--muted);font-size:.8rem}.status-callout strong{font-size:1.25rem}.side-actions{display:grid;gap:10px}.side-actions form,.side-actions button{width:100%}.corrective-card{border:1px solid var(--line);border-radius:18px;padding:18px;margin-top:14px;background:#fff}.corrective-head{display:flex;gap:18px;justify-content:space-between}.corrective-head h3{margin:.3rem 0}.corrective-head p{color:var(--muted)}.corrective-kpis{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.corrective-kpis span{padding:7px 10px;border-radius:999px;background:#f3f6f8;font-size:.82rem}.evidence-note{padding:12px;border-left:3px solid #111;background:#f8fafb}.corrective-update{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}.corrective-update label{display:grid;gap:5px}.feedback-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.event-list{display:grid;gap:10px}.event-list article{padding:14px;border:1px solid var(--line);border-radius:14px}.event-list article>div{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.event-list p{margin:.5rem 0}.event-list small{color:var(--muted)}.review-history-row{padding:12px 0;border-bottom:1px solid var(--line)}.review-history-row:last-child{border-bottom:0}.review-history-row strong,.review-history-row small{display:block}.review-history-row small{color:var(--muted);margin:.25rem 0}.review-history-row div{display:flex;justify-content:space-between;align-items:center}.metric-editor-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-top:18px}.metric-editor-grid article{border:1px solid var(--line);border-radius:14px;padding:12px}.metric-editor-grid article>span{display:block;font-weight:700;margin-bottom:8px}.metric-editor-grid label{display:grid;gap:4px;margin-top:6px}.metric-editor-grid input{width:100%}.form-actions{display:flex;justify-content:flex-end;margin-top:18px}@media(max-width:1200px){.performance-metrics{grid-template-columns:repeat(3,1fr)}.metric-editor-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.performance-hero,.performance-layout{grid-template-columns:1fr}.performance-layout aside{position:static}.feedback-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.performance-metrics,.feedback-grid,.metric-editor-grid,.corrective-update{grid-template-columns:1fr}.performance-hero{padding:20px}.corrective-head{flex-direction:column}}
</style>
